import{_ as e,a as d,o,a6 as r}from"./chunks/framework.CJDy2q7X.js";const h=JSON.parse('{"title":"List Products","description":"","frontmatter":{"outline":false,"examples":[{"id":"admin-catalog-products-list","title":"List Products (Datagrid)","description":"The canonical admin product listing — a cursor-paginated query mirroring the Catalog → Products datagrid, with every scalar column the listing can resolve.","query":"query AdminCatalogProducts(\\n  $first: Int\\n  $after: String\\n  $sku: String\\n  $type: String\\n  $status: Int\\n  $priceFrom: Float\\n  $priceTo: Float\\n) {\\n  adminCatalogProducts(\\n    first: $first\\n    after: $after\\n    sku: $sku\\n    type: $type\\n    status: $status\\n    price_from: $priceFrom\\n    price_to: $priceTo\\n  ) {\\n    edges {\\n      cursor\\n      node {\\n        id\\n        _id\\n        sku\\n        name\\n        type\\n        parentId\\n        status\\n        price\\n        formattedPrice\\n        specialPrice\\n        formattedSpecialPrice\\n        specialPriceFrom\\n        specialPriceTo\\n        quantity\\n        baseImageUrl\\n        imagesCount\\n        categoryId\\n        categoryName\\n        channel\\n        locale\\n        attributeFamilyId\\n        attributeFamilyName\\n        urlKey\\n        visibleIndividually\\n        shortDescription\\n        description\\n        metaTitle\\n        metaDescription\\n        metaKeywords\\n        weight\\n        featured\\n        new\\n        additional\\n        createdAt\\n        updatedAt\\n      }\\n    }\\n    pageInfo {\\n      hasNextPage\\n      hasPreviousPage\\n      startCursor\\n      endCursor\\n    }\\n    totalCount\\n  }\\n}\\n","variables":"{\\n  \\"first\\": 10,\\n  \\"sku\\": \\"SP-\\",\\n  \\"type\\": \\"simple\\",\\n  \\"status\\": 1\\n}\\n","response":"{\\n  \\"data\\": {\\n    \\"adminCatalogProducts\\": {\\n      \\"edges\\": [\\n        {\\n          \\"cursor\\": \\"MA==\\",\\n          \\"node\\": {\\n            \\"id\\": \\"/api/admin/catalog/products/22\\",\\n            \\"_id\\": 22,\\n            \\"sku\\": \\"SP-001\\",\\n            \\"name\\": \\"Acme Drawstring Bag\\",\\n            \\"type\\": \\"simple\\",\\n            \\"parentId\\": null,\\n            \\"status\\": \\"1\\",\\n            \\"price\\": \\"3000.0000\\",\\n            \\"formattedPrice\\": \\"$3,000.00\\",\\n            \\"specialPrice\\": \\"2700.0000\\",\\n            \\"formattedSpecialPrice\\": \\"$2,700.00\\",\\n            \\"specialPriceFrom\\": null,\\n            \\"specialPriceTo\\": null,\\n            \\"quantity\\": \\"98\\",\\n            \\"baseImageUrl\\": \\"http://localhost:8000/storage/product/22/1qfyoglc5BP46kofrxYrkJ2MXRxu9lAVG3BDFlTZ.webp\\",\\n            \\"imagesCount\\": \\"1\\",\\n            \\"categoryId\\": null,\\n            \\"categoryName\\": null,\\n            \\"channel\\": \\"default\\",\\n            \\"locale\\": \\"en\\",\\n            \\"attributeFamilyId\\": 1,\\n            \\"attributeFamilyName\\": \\"Default\\",\\n            \\"urlKey\\": \\"acme-drawstring-bag\\",\\n            \\"visibleIndividually\\": \\"1\\",\\n            \\"shortDescription\\": \\"Many desktop publishing packages and web page editors now use\\",\\n            \\"description\\": \\"A roomy drawstring bag in durable cotton canvas.\\",\\n            \\"metaTitle\\": \\"Acme Drawstring Bag\\",\\n            \\"metaDescription\\": \\"\\",\\n            \\"metaKeywords\\": \\"\\",\\n            \\"weight\\": \\"32\\",\\n            \\"featured\\": \\"1\\",\\n            \\"new\\": \\"\\",\\n            \\"additional\\": null,\\n            \\"createdAt\\": \\"2026-04-19T11:56:43+05:30\\",\\n            \\"updatedAt\\": \\"2026-04-23T16:36:14+05:30\\"\\n          }\\n        }\\n      ],\\n      \\"pageInfo\\": {\\n        \\"hasNextPage\\": true,\\n        \\"hasPreviousPage\\": false,\\n        \\"startCursor\\": \\"MA==\\",\\n        \\"endCursor\\": \\"MA==\\"\\n      },\\n      \\"totalCount\\": 265\\n    }\\n  }\\n}\\n"},{"id":"admin-catalog-products-sorted","title":"Sorted and Price-Filtered","description":"Sorting takes either a column plus a direction, or a single compound token. Both forms below are equivalent.","query":"query AdminCatalogProducts($first: Int, $sort: String, $order: String, $priceFrom: Float, $priceTo: Float) {\\n  adminCatalogProducts(\\n    first: $first\\n    sort: $sort\\n    order: $order\\n    price_from: $priceFrom\\n    price_to: $priceTo\\n  ) {\\n    edges {\\n      node {\\n        _id\\n        sku\\n        name\\n        price\\n        formattedPrice\\n      }\\n    }\\n    totalCount\\n  }\\n}\\n","variables":"{\\n  \\"first\\": 5,\\n  \\"sort\\": \\"price\\",\\n  \\"order\\": \\"asc\\",\\n  \\"priceFrom\\": 10,\\n  \\"priceTo\\": 500\\n}\\n","response":"{\\n  \\"data\\": {\\n    \\"adminCatalogProducts\\": {\\n      \\"edges\\": [\\n        {\\n          \\"node\\": {\\n            \\"_id\\": 85,\\n            \\"sku\\": \\"SP-014\\",\\n            \\"name\\": \\"PureStride Classic White Sneakers\\",\\n            \\"price\\": \\"60.9900\\",\\n            \\"formattedPrice\\": \\"$60.99\\"\\n          }\\n        }\\n      ],\\n      \\"totalCount\\": 41\\n    }\\n  }\\n}\\n"}]},"headers":[],"relativePath":"api/graphql-api/admin/catalog/products.md","filePath":"api/graphql-api/admin/catalog/products.md","lastUpdated":1787725411000}'),a={name:"api/graphql-api/admin/catalog/products.md"};function n(c,t,i,s,l,u){return o(),d("div",null,t[0]||(t[0]=[r('<h1 id="list-products" tabindex="-1">List Products <a class="header-anchor" href="#list-products" aria-label="Permalink to &quot;List Products&quot;">​</a></h1><p>The canonical admin product listing, mirroring the Bagisto admin <strong>Catalog → Products</strong> datagrid. Cursor-paginated, filterable, and sortable — this is the query behind a product-management screen.</p><p>For the product types, the two-step create flow, <code>status</code> versus <code>visibleIndividually</code>, and the per-product sub-resources, see the <a href="/api/graphql-api/admin/catalog/products/">Products overview</a>.</p><p>A separate slim search, <a href="/api/graphql-api/admin/catalog/products/list.html"><code>adminProducts</code></a>, powers the Create-Order &quot;Add Product&quot; modal only. It is not the listing.</p><h2 id="operation" tabindex="-1">Operation <a class="header-anchor" href="#operation" aria-label="Permalink to &quot;Operation&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Operation</th><th>Type</th><th>Pagination</th></tr></thead><tbody><tr><td><code>adminCatalogProducts</code></td><td>Query</td><td>Cursor (<code>first</code> / <code>after</code>)</td></tr></tbody></table><h2 id="arguments" tabindex="-1">Arguments <a class="header-anchor" href="#arguments" aria-label="Permalink to &quot;Arguments&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Argument</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>first</code></td><td>Int</td><td>Page size, default <code>10</code>, capped at <code>50</code>.</td></tr><tr><td><code>after</code></td><td>String</td><td>Cursor from a previous <code>pageInfo.endCursor</code>.</td></tr><tr><td><code>last</code></td><td>Int</td><td>Page size when paging backwards.</td></tr><tr><td><code>before</code></td><td>String</td><td>Cursor from a previous <code>pageInfo.startCursor</code>.</td></tr><tr><td><code>product_id</code></td><td>String</td><td>One id (<code>&quot;142&quot;</code>) or a comma-separated list (<code>&quot;1,2,3&quot;</code>).</td></tr><tr><td><code>sku</code></td><td>String</td><td>Partial SKU match.</td></tr><tr><td><code>name</code></td><td>String</td><td>Partial name match.</td></tr><tr><td><code>type</code></td><td>String</td><td><code>simple</code>, <code>configurable</code>, <code>bundle</code>, <code>grouped</code>, <code>downloadable</code>, <code>virtual</code>, or <code>booking</code>.</td></tr><tr><td><code>status</code></td><td>Int</td><td><code>0</code> disabled, <code>1</code> enabled.</td></tr><tr><td><code>attribute_family</code></td><td>String</td><td>Attribute family id.</td></tr><tr><td><code>channel</code></td><td>String</td><td>Channel code used to resolve values. Defaults to the current channel.</td></tr><tr><td><code>locale</code></td><td>String</td><td>Locale code used to resolve name and category. Defaults to the app locale.</td></tr><tr><td><code>price_from</code></td><td>Float</td><td>Minimum price, inclusive.</td></tr><tr><td><code>price_to</code></td><td>Float</td><td>Maximum price, inclusive.</td></tr><tr><td><code>sort</code></td><td>String</td><td>Column to sort by — see <a href="#sorting">Sorting</a>.</td></tr><tr><td><code>order</code></td><td>String</td><td><code>asc</code> or <code>desc</code>. Defaults to <code>desc</code>.</td></tr></tbody></table><p>Filters combine with AND, so each one you add narrows the result. Four of the argument names are snake_case (<code>product_id</code>, <code>attribute_family</code>, <code>price_from</code>, <code>price_to</code>) while the rest are single words — that is the literal schema, not a typo.</p><h2 id="node-fields" tabindex="-1">Node Fields <a class="header-anchor" href="#node-fields" aria-label="Permalink to &quot;Node Fields&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td>ID!</td><td>Resource identifier in IRI form, <code>/api/admin/catalog/products/&lt;id&gt;</code>.</td></tr><tr><td><code>_id</code></td><td>Int!</td><td>Numeric product id.</td></tr><tr><td><code>sku</code></td><td>String!</td><td>Product SKU.</td></tr><tr><td><code>type</code></td><td>String!</td><td>Product type.</td></tr><tr><td><code>parentId</code></td><td>String</td><td>Parent product id for a configurable variant, <code>null</code> for a standalone product.</td></tr><tr><td><code>name</code></td><td>String</td><td>Resolved for the requested channel and locale.</td></tr><tr><td><code>status</code></td><td>String</td><td><code>&quot;1&quot;</code> enabled, <code>&quot;&quot;</code> disabled.</td></tr><tr><td><code>price</code></td><td>String</td><td>Decimal string, four places (<code>&quot;3000.0000&quot;</code>).</td></tr><tr><td><code>formattedPrice</code></td><td>String</td><td>The same price in the channel currency.</td></tr><tr><td><code>specialPrice</code></td><td>String</td><td>Sale price as a decimal string, <code>null</code> when none.</td></tr><tr><td><code>formattedSpecialPrice</code></td><td>String</td><td>Formatted sale price, <code>null</code> when none.</td></tr><tr><td><code>specialPriceFrom</code></td><td>String</td><td>Start of the sale window, <code>null</code> unless a dated window is set.</td></tr><tr><td><code>specialPriceTo</code></td><td>String</td><td>End of the sale window, <code>null</code> unless a dated window is set.</td></tr><tr><td><code>quantity</code></td><td>String</td><td>Inventory summed across every source.</td></tr><tr><td><code>baseImageUrl</code></td><td>String</td><td>URL of the first product image.</td></tr><tr><td><code>imagesCount</code></td><td>String</td><td>Number of images attached.</td></tr><tr><td><code>categoryId</code></td><td>String</td><td>Id of the <strong>first</strong> category only, <code>null</code> when uncategorized.</td></tr><tr><td><code>categoryName</code></td><td>String</td><td>Translated name of that first category.</td></tr><tr><td><code>channel</code></td><td>String</td><td>Channel code used for resolution.</td></tr><tr><td><code>locale</code></td><td>String</td><td>Locale code used for resolution.</td></tr><tr><td><code>attributeFamilyId</code></td><td>Int</td><td>Attribute family id.</td></tr><tr><td><code>attributeFamilyName</code></td><td>String</td><td>Attribute family name.</td></tr><tr><td><code>urlKey</code></td><td>String</td><td>URL slug.</td></tr><tr><td><code>visibleIndividually</code></td><td>String</td><td><code>&quot;1&quot;</code> when the product appears in listings, <code>&quot;&quot;</code> when it does not.</td></tr><tr><td><code>shortDescription</code></td><td>String</td><td>Short description, HTML.</td></tr><tr><td><code>description</code></td><td>String</td><td>Full description, HTML.</td></tr><tr><td><code>metaTitle</code></td><td>String</td><td>SEO meta title.</td></tr><tr><td><code>metaDescription</code></td><td>String</td><td>SEO meta description.</td></tr><tr><td><code>metaKeywords</code></td><td>String</td><td>SEO meta keywords.</td></tr><tr><td><code>weight</code></td><td>String</td><td>Product weight.</td></tr><tr><td><code>featured</code></td><td>String</td><td><code>&quot;1&quot;</code> when flagged featured, <code>&quot;&quot;</code> when not.</td></tr><tr><td><code>new</code></td><td>String</td><td><code>&quot;1&quot;</code> when flagged new, <code>&quot;&quot;</code> when not.</td></tr><tr><td><code>additional</code></td><td>String</td><td>Type-specific extra data, <code>null</code> for most products.</td></tr><tr><td><code>createdAt</code></td><td>String</td><td>ISO 8601 with offset, <code>2026-04-19T11:56:43+05:30</code>.</td></tr><tr><td><code>updatedAt</code></td><td>String</td><td>ISO 8601 with offset.</td></tr></tbody></table><p>Four traps in these values:</p><ul><li><strong>Booleans arrive as <code>&quot;1&quot;</code> or the empty string <code>&quot;&quot;</code>, never <code>true</code>/<code>false</code>.</strong> <code>status</code>, <code>visibleIndividually</code>, <code>featured</code>, and <code>new</code> are all typed String. <code>&quot;&quot;</code> is falsy in JavaScript so a plain <code>if (node.featured)</code> happens to work, but <code>node.featured === false</code> and <code>node.status === &quot;0&quot;</code> never match anything. Compare against <code>&quot;1&quot;</code>, or coerce.</li><li><strong>Numbers arrive as strings too.</strong> <code>price</code>, <code>quantity</code>, <code>imagesCount</code>, <code>weight</code>, and <code>categoryId</code> are String; only <code>_id</code> and <code>attributeFamilyId</code> are Int. Sorting a page client-side on <code>price</code> without casting compares <code>&quot;100.0000&quot;</code> below <code>&quot;60.9900&quot;</code>.</li><li><strong><code>categoryId</code> and <code>categoryName</code> describe the first category only.</strong> A product in three categories reports one, matching what the datagrid shows. Read the full set from the <code>categories</code> connection on <a href="/api/graphql-api/admin/catalog/products/products-detail.html">Product Detail</a>.</li><li><strong><code>quantity</code> is a sum across inventory sources</strong>, not a per-source figure. For the breakdown use <a href="/api/graphql-api/admin/catalog/products/inventories-list.html">List Inventories</a>.</li></ul><h3 id="fields-that-stay-null-on-the-listing" tabindex="-1">Fields That Stay Null on the Listing <a class="header-anchor" href="#fields-that-stay-null-on-the-listing" aria-label="Permalink to &quot;Fields That Stay Null on the Listing&quot;">​</a></h3><p><code>taxCategoryId</code>, <code>manageStock</code>, and <code>inStock</code> are resolved per product and are always <code>null</code> here. So is every relation connection — <code>translations</code>, <code>images</code>, <code>videos</code>, <code>categories</code>, <code>inventories</code>, <code>customerGroupPrices</code>, <code>superAttributes</code>, <code>variants</code>, <code>bundleOptions</code>, <code>linkedProducts</code>, <code>downloadableLinks</code>, <code>downloadableSamples</code>, <code>customizableOptions</code>, <code>attributeValues</code>, <code>channels</code>, <code>relatedProducts</code>, <code>upSells</code>, and <code>crossSells</code>. They resolve only on <code>adminCatalogProduct(id:)</code>.</p><p>Selecting them on the listing is not an error — you simply get nulls and empty edges, at no query cost.</p><h2 id="sorting" tabindex="-1">Sorting <a class="header-anchor" href="#sorting" aria-label="Permalink to &quot;Sorting&quot;">​</a></h2><p>Pass <code>sort</code> with a column and <code>order</code> with a direction. The compound form <code>sort: &quot;name-asc&quot;</code> is also accepted and splits on the hyphen.</p><table tabindex="0"><thead><tr><th><code>sort</code> value</th><th>Sorts by</th></tr></thead><tbody><tr><td><code>product_id</code></td><td>Product id (default)</td></tr><tr><td><code>name</code></td><td>Product name</td></tr><tr><td><code>sku</code></td><td>SKU</td></tr><tr><td><code>price</code></td><td>Price</td></tr><tr><td><code>quantity</code></td><td>Inventory quantity, summed across sources</td></tr><tr><td><code>status</code></td><td>Enabled / disabled</td></tr><tr><td><code>type</code></td><td>Product type</td></tr><tr><td><code>attribute_family</code></td><td>Attribute family id</td></tr><tr><td><code>channel</code></td><td>Channel code</td></tr></tbody></table><p>Products with no resolved <code>name</code> in the requested locale sort first on an ascending <code>name</code> — they are not filtered out.</p><h2 id="cursor-pagination" tabindex="-1">Cursor Pagination <a class="header-anchor" href="#cursor-pagination" aria-label="Permalink to &quot;Cursor Pagination&quot;">​</a></h2><p><code>first</code> sets the page size. Pass the previous response&#39;s <code>pageInfo.endCursor</code> as <code>after</code> to advance. <code>totalCount</code> is the full match count across all pages, not the size of the current page.</p><h2 id="how-it-differs-from-adminproducts" tabindex="-1">How It Differs From <code>adminProducts</code> <a class="header-anchor" href="#how-it-differs-from-adminproducts" aria-label="Permalink to &quot;How It Differs From `adminProducts`&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th><code>adminCatalogProducts</code></th><th><code>adminProducts</code></th></tr></thead><tbody><tr><td>Purpose</td><td>The product listing, for catalog management</td><td>Create-Order &quot;Add Product&quot; search</td></tr><tr><td>Row shape</td><td>Every scalar column</td><td>Nine fields</td></tr><tr><td>Filters</td><td>Full set including price range and attribute family</td><td>Free text, sku, type, status, categoryId</td></tr><tr><td>Scalar types</td><td>Strings, including the numbers and booleans</td><td>Real <code>Int</code>, <code>Float</code>, and <code>Boolean</code></td></tr><tr><td>Default status filter</td><td>None — all statuses returned</td><td>None — all statuses returned</td></tr></tbody></table><p>The scalar-type difference is the one that bites: the two queries describe the same products with different JSON types, so a shared parsing helper will break on one of them.</p><h2 id="search-engine" tabindex="-1">Search Engine <a class="header-anchor" href="#search-engine" aria-label="Permalink to &quot;Search Engine&quot;">​</a></h2><p>The listing always queries the database. Configuring the admin panel to use Elasticsearch for catalog search does not change this query&#39;s behaviour.</p>',27)]))}const g=e(a,[["render",n]]);export{h as __pageData,g as default};
